"""Карточки гипотез для теста с 22.10.2026. Версия 4. Цифры — из data/mediaplan.csv (notes/scripts/mediaplan.py).
Пороги — при базовом чеке (забор: медиана сумм заказов в отзывах; пакет: прозвон 350–450 тыс. ₽; привод: 42 700 ₽):
  порог заявки = 11% чека × закрытие; остановка — заявка дороже двух порогов или нет заявок; продолжение — цена заказа ≤ 11% среднего чека
  первых договоров и заявка не дороже порога. Выход: data/hypotheses.csv. Запуск: python3 -I build_hypotheses.py"""
import csv, statistics as st
B = '/home/claude/zabory'
mp = list(csv.DictReader(open(f'{B}/data/mediaplan.csv', encoding='utf-8')))
OS = [int(r['sum_rub']) for r in csv.DictReader(open(f'{B}/data/order_sums_reviews.csv', encoding='utf-8')) if r['included'] == 'да']
BASE_CHECK = {'забор': (st.median(OS), st.median(OS)), 'пакет': (350000, 450000), 'привод': (42700, 42700)}
AD, CLOSE, AV_CLOSE = 0.11, 0.09, 0.023
def sp(x): return f'{int(round(float(x))):,}'.replace(',', ' ')
def rows_of(h): return [r for r in mp if r['hypothesis_id'] == h]
def verdicts(r):
    return '; '.join(f"{r[f'check{i}_name']}: {r[f'check{i}_ad_share']} чека — {r[f'check{i}_verdict']}" for i in (1, 2, 3) if r[f'check{i}_name'] != '—')

QUAL = ('Квалифицированная заявка: адрес в Москве или МО; нужен монтаж под ключ (не покупка материала без монтажа); '
        'названы длина забора или проём ворот; клиент согласен на замер в течение 30 дней; телефон или мессенджер отвечает')
CARDS = [
 ('H1', 'Забор под ключ: итоговая сумма в договоре после бесплатного замера, гарантия на покраску и столбы «после первой зимы» с весенним осмотром; оплата — по решению заказчика (после приёмки или аванс). В квизе вопрос «дом / дача»',
  'Поиск: «забор под ключ», «установка забора», «забор из профнастила под ключ», «забор из евроштакетника», «забор жалюзи», «забор в московской области», «монтаж забора цена», «заказать забор»; гео Москва и МО',
  'Блоки идеальной страницы: 1, 2, 4, 5 (итог без телефона, смета в мессенджер), 8, 9, 12, 13, 14, 15', '22.10–11.11.2026 (21 день)', 20000, 40000, 'C41 монтаж, C28 связь после оплаты, C18 покрытие, C27 гарантия, C09 смета'),
 ('H2', 'Пакет «забор + откатные ворота 4 м с автоматикой + калитка» с итоговой суммой для участка 6, 10 и 12 соток; монтаж одной бригадой; 3 года обслуживания автоматики',
  'Поиск: «забор с откатными воротами», «откатные ворота под ключ цена с установкой», «откатные ворота с калиткой под ключ», «откатные ворота цена с установкой в московской области»',
  'Блоки: 1 (пакет и итоговая сумма), 6, 4, 5, 2, 9, 11, 12, 15',
  '22.10–18.11.2026 (28 дней); ёмкость 161–172 клика за срок, бюджет 14 000 ₽ даёт 113–164 клика; при CTR ниже 5% бюджет не открутится — продлить срок или расширить семантику (оценка)', 9000, 12000, 'C22 пакет, C21 цена ворот, C23 сервис автоматики'),
 ('H3', '«Весна по цене октября»: договор и замер сейчас, цена и дата монтажа закрепляются в договоре',
  'РСЯ: аудитории по запросам о заборах и воротах за 30 дней, ретаргетинг посетителей H1–H2; гео МО', 'Блоки: 1, 7, 8, 5, 12, 15', '22.10–18.11.2026 (28 дней)', 15000, 25000, 'C09 смета, C14 срок; межсезонье'),
 ('H4', 'Смета в мессенджер за 1 час и цена, которая не меняется после замера; пакет с воротами',
  'VK Реклама: лид-форма или сообщения сообщества; гео — города МО из подсказок; интересы «строительство и ремонт», «загородная недвижимость»',
  'Лид-форма 4–5 вопросов (материал, длина, ворота, дом или дача, сроки) → автоответ со сметой; посадочная H1 сокращённая: 1, 5, 2, 10, 11, 15', '22.10–11.11.2026 (21 день)', 10000, 20000, 'C44 письменное КП, C16 скорость ответа, C09 смета'),
 ('H5', 'Привод на уже стоящие откатные ворота за 1 день с монтажом и настройкой; 3 года обслуживания',
  'Поиск: «привод для откатных ворот», «автоматика для откатных ворот с установкой», «ремонт откатных ворот»; гео Москва и МО', 'Отдельная короткая страница: 1, 6, 12, 15',
  '22.10–18.11.2026 (28 дней); ёмкость около 55 кликов за срок, ожидается около 1 заявки (оценка)', 2500, 4000, 'C23 сервис автоматики; приводы +20,8% за год (исследование ворот)'),
 ('H7', 'Карточка «Дома гирлянд — заборы и въездные группы»: витрина трёх пакетов с итоговой суммой, акция «итоговая сумма в договоре», сторис с фото-актом',
  'Яндекс Карты: запросы «заборы», «забор под ключ», «откатные ворота», «установка заборов»; у всех 10 первых карточек по этим запросам есть реклама (21.10.2026)',
  'Карточка организации: витрина, акция, кнопка «Написать», ссылка на посадочную H2', '22.10–18.11.2026 (28 дней); у новой карточки нет отзывов — риск низкого отклика', 7500, 15000, 'C22 пакет, C01 отзывы (на старте 0)'),
 ('H8', 'Забор и въезд под ключ: итоговая сумма в договоре; в объявлении цена с единицей и составом (единица цены указана у 16 из 249 уникальных объявлений, 21.10)',
  'Авито: «забор под ключ» и «откатные ворота» (Москва), «установка забора» (МО). Рынок 21.10 (3 запроса × 100 объявлений, 249 уникальных): профнастил — медиана 700 ₽/п.м. (n=33, единица — оценка), откатные ворота — от 41 000 ₽ (медиана, n=13); объявление об установке ворот — около 11 просмотров в день (оценка сверху); верх выдачи в Москве — компании (17 из 20 по «забор под ключ»), в МО — частные мастера (17 из 20 по «установка забора»)',
  'Объявление с прайсом из трёх пакетов и составом; переход в мессенджер и на посадочную H1',
  '22.10–11.11.2026 (21 день); цена продвижения и число контактов снаружи не видны — только в кабинете продавца', 7000, 12000, 'C08 прозрачность цены, C09 смета'),
]
out = []
for hid, offer, sem, land, period, stop_zero, stop_spend, crit in CARDS:
    rr = rows_of(hid); base = rr[0]; seg = base['segment_check']
    others = rr[1:]
    chk = BASE_CHECK[seg]
    close = AV_CLOSE if hid == 'H8' else CLOSE
    thr = (AD * chk[0] * close, AD * chk[1] * close)
    if hid == 'H8':
        stop = (f'Остановить, если после {sp(stop_zero)} ₽ цена обращения выше 339 ₽ (верх кейсов Авито) или после {sp(stop_spend)} ₽ ни одного замера; '
                f'реклама дороже {sp(thr[0])} ₽ за обращение при закрытии 2,3% даёт цену заказа выше 11% базового чека')
        scale = (f'Продолжить, если цена заказа (расходы / договоры) ≤ 11% среднего чека заключённых договоров; ориентир — обращение ≤ {sp(thr[0])} ₽ '
                 f'при закрытии 2,3% и чеке {sp(chk[0])} ₽; при чеке модели 67 600 ₽ — ≤ 171 ₽')
    elif hid == 'H7':
        stop = f'Остановить, если после {sp(stop_zero)} ₽ меньше 3 обращений (звонки, сообщения, маршруты) или после {sp(stop_spend)} ₽ ни одной квалифицированной заявки'
        scale = f'Продолжить, если цена заказа ≤ 11% среднего чека первых договоров; ориентир — квалифицированная заявка ≤ {sp(thr[0])}–{sp(thr[1])} ₽ (пакет 350–450 тыс. ₽)'
    else:
        stop = (f'Остановить или сменить оффер, если после {sp(stop_zero)} ₽ нет ни одной заявки, либо после {sp(stop_spend)} ₽ цена заявки выше {sp(2 * thr[1])} ₽ '
                f'(2 × порог «реклама = 11% чека» при базовом чеке), либо квалифицированных меньше 50%')
        scale = (f'Сохранить на весну и увеличивать бюджет, если цена заявки ≤ {sp(thr[0])} ₽ (порог при базовом чеке {sp(chk[0])}'
                 + (f'–{sp(chk[1])}' if chk[1] != chk[0] else '') + ' ₽), квалифицированных ≥ 60% и средний чек первых КП не ниже базового')
    lbl = 'ГИПОТЕЗА; бюджет — допущение; конверсии и закрытие — оценка'
    if base['cpc_rub'] != 'не применяется':
        lbl += '; CPC — диапазон 85–124 ₽ (Keys.so — Spywords по masterovit.ru), крайние 71–245 ₽'
    out.append({
        'hypothesis_id': hid, 'offer': offer, 'channel': base['channel'], 'semantics_audience': sem, 'landing_blocks': land,
        'budget_rub_assumption': base['budget_rub_assumption'], 'test_period': period, 'cpc_rub': base['cpc_rub'],
        'base_scenario': base['scenario'], 'expected_cpl_rub': base['cpl_rub'], 'expected_orders': base['orders'], 'expected_cpo_rub': base['cpo_rub'],
        'verdict_by_check': verdicts(base) if base['check1_verdict'] != 'не считается' else 'не считается',
        'other_scenarios': ' | '.join(f"{r['scenario']}: заявка {r['cpl_rub']} ₽, заказ {r['cpo_rub']} ₽; {verdicts(r)}" for r in others) if others else '—',
        'base_check_rub': sp(chk[0]) + ('' if chk[1] == chk[0] else '–' + sp(chk[1])),
        'threshold_cpl_ad11pct_rub': sp(thr[0]) + ('' if thr[1] == thr[0] else '–' + sp(thr[1])),
        'main_metric': 'цена заявки, конверсия страницы, доля квалифицированных и средний чек первых КП; заказов за тест 0–4 — для решения мало',
        'qualified_lead_definition': QUAL, 'stop_rule': stop, 'scale_rule': scale, 'criteria_tested': crit, 'label': lbl, 'date': '2026-10-21'})
pk = BASE_CHECK['пакет']
out.append({
    'hypothesis_id': 'H6', 'offer': 'Клиентам «Дома гирлянд» с частными домами: «Периметр под ключ» — забор и въезд с итоговой суммой в договоре, подсветка въезда в пакете',
    'channel': 'База клиентов «Дома гирлянд»: сообщение в мессенджер или СМС + звонок менеджера',
    'semantics_audience': 'Клиенты с частными домами в Москве и МО (из CRM «Дома гирлянд»); первый канал по исследованию заборов 13.10.2026',
    'landing_blocks': 'Посадочная H1 с блоком «для клиентов Дома гирлянд»: 1, 5, 6, 12, 15', 'budget_rub_assumption': 10000, 'test_period': '22.10–11.11.2026 (21 день)',
    'cpc_rub': 'не применяется', 'base_scenario': 'не считается: размер базы и доля владельцев домов не найдены', 'expected_cpl_rub': 'не считается', 'expected_orders': '—',
    'expected_cpo_rub': '—', 'verdict_by_check': 'не считается', 'other_scenarios': '—', 'base_check_rub': f'{sp(pk[0])}–{sp(pk[1])}',
    'threshold_cpl_ad11pct_rub': f'{sp(AD * pk[0] * CLOSE)}–{sp(AD * pk[1] * CLOSE)}',
    'main_metric': 'доля ответивших, заявок на 100 контактов, цена заявки = расходы на рассылку и звонки / заявки', 'qualified_lead_definition': QUAL,
    'stop_rule': 'Остановить, если после двух касаний заявок меньше 1 на 100 контактов (оценка порога) или больше 2% отписок',
    'scale_rule': 'Продолжить и делать регулярной, если цена заказа ≤ 11% среднего чека первых договоров и квалифицированных ≥ 60%',
    'criteria_tested': 'персонаж «владелец дома»; C22 пакет; доверие к знакомому бренду', 'label': 'ГИПОТЕЗА; размер базы не найден — заполняет заказчик; бюджет — допущение', 'date': '2026-10-21'})
with open(f'{B}/data/hypotheses.csv', 'w', encoding='utf-8', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(out[0].keys())); w.writeheader(); w.writerows(out)
print('total budget', sum(int(r['budget_rub_assumption']) for r in out))
for r in out:
    print(r['hypothesis_id'], r['budget_rub_assumption'], r['expected_cpl_rub'], r['expected_cpo_rub'], '| thr', r['threshold_cpl_ad11pct_rub'])
    print('   V:', r['verdict_by_check'][:300]); print('   S:', r['stop_rule']); print('   +:', r['scale_rule'])
